def _filter_deployments_by_model_access_groups(
        self,
        model: str,
        healthy_deployments: List,
        request_kwargs: Optional[Dict],
        request_team_id: Optional[str],
    ) -> List:
        """
        Restrict candidate deployments to caller-authorized model access groups.

This is only applied when:
        - request metadata includes `user_api_key_auth`, and
        - caller permissions for this model are access-group-only
          (no explicit model, wildcard, or all-proxy grants).
        """
        if not healthy_deployments or request_kwargs is None:
            return healthy_deployments

metadata = request_kwargs.get("metadata") or {}
        litellm_metadata = request_kwargs.get("litellm_metadata") or {}
        user_api_key_auth = metadata.get("user_api_key_auth") or litellm_metadata.get("user_api_key_auth")
        if user_api_key_auth is None:
            return healthy_deployments

object_models = set(getattr(user_api_key_auth, "models", []) or [])
        object_team_models = set(getattr(user_api_key_auth, "team_models", []) or [])
        allowed_models = object_models | object_team_models
        if not allowed_models:
            return healthy_deployments

# If caller has direct model/wildcard/all-proxy access, do not constrain
        # deployment choice by access group.
        if model in allowed_models or "*" in allowed_models or "all-proxy-models" in allowed_models:
            return healthy_deployments

access_groups_for_model = self.get_model_access_groups(model_name=model, team_id=request_team_id)
        if len(access_groups_for_model) == 0:
            return healthy_deployments","content_hash":"53094fa453f71bd8a487151cc6fc67ed7747cdf490b92711127a1dc1eed0f4e2","chunk_metadata":{"ordinal":278,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/litellm-34399-kaitlyn","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00278","vector":{"bm25":{"indices":[11611662,21141582,24962933,52788261,131900689,136345932,152217691,160273134,220143199,344065877,402167784,403465192,416094519,448220673,453950983,454222729,455026286,491396510,520427161,523661903,544304585,550693654,551536775,553793032,572399988,609270800,630986436,640124220,653705362,684900361,716765060,717265138,728008763,753185237,764297089,766710245,772165269,780249753,790716753,814527388,819423458,823134346,823588779,835204381,835950486,883390095,888000370,896827128,912056712,917314569,917955627,920073456,923945757,926244272,957794642,968579947,997012898,1009084850,1021187622,1063320047,1120495519,1132748958,1153295626,1169853166,1172010017,1172383616,1174952987,1202493479,1241252119,1245654145,1258039968,1276838843,1293458094,1297380231,1299665196,1321157110,1331432587,1356667733,1418522856,1418910227,1430125705,1480764286,1515372845,1518651811,1519078073,1539641452,1581361369,1610788695,1615682969,1620849882,1636998148,1662505136,1670483617,1678348498,1679435792,1707643534,1717991430,1742836257,1750975000,1751311563,1761927089,1763574823,1790431914,1792659531,1810936627,1830646559,1833610515,1838535212,1838689002,1853176582,1887486930,1904577663,1958928658,1986137636,1998848851,2074315840,2120211764,2126841918,2134303291,2142141949,2143830595],"values":[1.7049875,1.0178926,1.3918201,1.0178926,1.5860322,1.0178926,1.7853293,1.0178926,1.0178926,1.5860322,1.0178926,1.0178926,1.0178926,1.0178926,1.0178926,1.0178926,1.8432335,1.9710916,1.3918201,1.3918201,1.0178926,1.3918201,1.0178926,1.0178926,1.5860322,1.0178926,1.3918201,1.0178926,1.0178926,1.0178926,1.3918201,1.3918201,1.5860322,1.0178926,1.7049875