def _filter_by_routing_plugin_candidates(
        self,
        healthy_deployments: Union[list[dict], dict],
        request_kwargs: dict,
    ) -> Union[list[dict], dict]:
        """
        Narrow `healthy_deployments` to whatever `self.routing_plugins` left in
        `context.candidate_models`. Raises rather than silently falling back to
        the unfiltered pool -- a plugin narrowing to nothing is a policy decision
        (e.g. no model this tenant's budget allows), not something to bypass.
        """
        if not self.routing_plugins or not isinstance(healthy_deployments, list):
            return healthy_deployments

metadata_key = self._get_metadata_variable_name_from_kwargs(request_kwargs)
        candidate_models = (request_kwargs.get(metadata_key) or {}).get("_routing_plugin_candidate_models")
        # `is None` (not falsy-check): a plugin narrowing to an empty list must
        # still hit the "no deployments left" raise below, not be treated the
        # same as "no plugin ever set this key".
        if candidate_models is None:
            return healthy_deployments

candidate_set = set(candidate_models)
        filtered = [d for d in healthy_deployments if d.get("litellm_params", {}).get("model") in candidate_set]

if not filtered:
            raise ValueError(f"No deployments left after routing-plugin filtering. candidate_models={candidate_models}")

return filtered","content_hash":"b1a41ff8854c7e92053d99cd41038bcb12a53d47978892f400e5f19342d0b1b9","chunk_metadata":{"ordinal":290,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/litellm-34399-kaitlyn","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00290","vector":{"bm25":{"indices":[4458511,47667107,65801163,117848935,131900689,136345932,146209276,152760128,176587294,224121762,243905464,350962655,392757719,402167784,403465192,416094519,428558603,433094314,438080992,440359455,443994268,448220673,454222729,491396510,505715833,523661903,530764119,550693654,563226112,568570484,572399988,609812654,612813868,654114448,655955059,667623065,672811249,685484366,717265138,727902867,740425643,746228801,747221668,753371676,753381197,766710245,772165269,795106543,824622370,846818121,856304565,917314569,920073456,926244272,926680089,951234652,956524161,965664421,997012898,1004015569,1009084850,1050315610,1083803674,1119753640,1131356383,1132748958,1135795808,1139959774,1150939219,1153908502,1169853166,1170138678,1172383616,1174952987,1200518484,1219477914,1252059351,1258039968,1276444565,1297380231,1331432587,1334412780,1349791844,1356667733,1424238030,1427057943,1430125705,1515372845,1519078073,1526557164,1528994750,1539641452,1561499504,1562546716,1610788695,1615682969,1619210490,1673929811,1701593959,1751311563,1763574823,1783853342,1803723570,1834582479,1838689002,1853176582,1866402814,1887486930,1968306389,1970308082,1982804121,1986137636,1986882737,1996994747,1998848851,2021799277,2045916435,2087367745,2126841918,2128227386,2143830595],"values":[1.1040972,1.1040972,1.1040972,1.6530672,1.6530672,1.1040972,1.1040972,1.4703041,1.1040972,1.1040972,1.4703041,1.1040972,1.1040972,1.1040972,1.1040972,1.1040972,1.1040972,1.1040972,1.4703041,1.1040972,1.4703041,1.1040972,1.1040972,1.6530672,1.1040972,1.1040972,1.1040972,1.6530672,1.7626164,1.1040972,1.4703041,1.1040972,1.4703041,1.1040972,1.6530672,1.4703041,1.4703041,1.10