            team_public_model_name = model_info.get("team_public_model_name")
            if team_public_model_name:
                names.append(team_public_model_name)
            is_unhealthy = model_info.get("id") in unhealthy_ids
            for name in names:
                if not name:
                    continue
                if name in unhealthy_by_name:
