        """
        Return True if model access group is a wildcard route
        """
        # GET ACCESS GROUPS
        access_groups = self.get_model_access_groups(model_access_group=model_access_group)

if len(access_groups) == 0:
            return False

models = access_groups.get(model_access_group, [])

for model in models:
