def get_available_deployment(
        self,
        model: str,
        messages: Optional[List[Dict[str, str]]] = None,
        input: Optional[Union[str, List]] = None,
        specific_deployment: Optional[bool] = False,
        request_kwargs: Optional[Dict] = None,
    ):
        """
        Returns the deployment based on routing strategy
        """
        if self.routing_plugins:
            raise ValueError(
                "Router(plugins=[...]) is configured, but this call resolved to the synchronous "
                "deployment-selection path, which never runs the routing-plugin pipeline. This "
                "happens for sync Router methods (e.g. Router.completion()) and for async calls "
                "with a routing_strategy that has no async-native selector (e.g. legacy "
                "'usage-based-routing', v1). Silently skipping "
                "configured plugins would let a policy plugin (e.g. a deny-all rule) be bypassed. "
                "Use an async Router method with a supported routing_strategy (simple-shuffle, "
                "usage-based-routing-v2, cost-based-routing, latency-based-routing, least-busy), "
                "or remove `plugins` from the Router config."
            )
        # users need to explicitly call a specific deployment, by setting `specific_deployment = True` as completion()/embedding() kwarg
        # When this was no explicit we had several issues with fallbacks timing out

model, healthy_deployments = self._common_checks_available_deployment(
            model=model,
            messages=messages,
            input=input,
            specific_deployment=specific_deployment,
            request_kwargs=request_kwargs,
        )","content_hash":"2c6e89e13ccd52b50cde938c227647c210200a5fe338dfb35a7f367974b103a2","chunk_metadata":{"ordinal":294,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/litellm-34399-kaitlyn","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00294","vector":{"bm25":{"indices":[11875599,29391631,131900689,133569021,136345932,152217691,179720517,242555882,392757719,402167784,428224343,428684691,438080992,448220673,454222729,482263480,491396510,493065660,521663532,523529899,550693654,553793032,555641829,563226112,568570484,572399988,594058293,596788688,632657554,653705362,672811249,717265138,761953944,764297089,766710245,772165269,806276788,815826517,816593518,896827128,897065139,920073456,926244272,951234652,997012898,1031166389,1132748958,1135795808,1172383616,1197919340,1240929146,1245654145,1258039968,1275986279,1306685010,1315682275,1331432587,1339244007,1399499421,1430125705,1449660732,1458844851,1466174222,1515372845,1519078073,1537687150,1539641452,1551883195,1592603301,1605015950,1610788695,1615682969,1662505136,1701593959,1751311563,1763574823,1775054672,1803723570,1826076852,1827736854,1838689002,1853176582,1871822857,1887486930,1892714830,1927364323,1969182875,1986137636,1998848851,2007450916,2021799277,2028263370,2036920246,2054925129,2064885619,2129085117,2143830595],"values":[1.1901944,1.1901944,1.1901944,1.7149817,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.5447066,1.1901944,1.1901944,1.1901944,1.8150177,1.7149817,1.1901944,1.1901944,1.8150177,1.1901944,1.1901944,1.8150177,1.1901944,1.7149817,1.1901944,1.1901944,1.1901944,1.7149817,1.5447066,1.5447066,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.7149817,1.1901944,1.8808442,1.1901944,1.1901944,1.5447066,1.1901944,1.9890517,1.5447066,1.9890517,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.1901944,1.5447066,1.1901944,1.5447066,1.1901944,1.1901944,1.190194