def _filter_cooldown_deployments(
        self, healthy_deployments: List[Dict], cooldown_deployments: List[str]
    ) -> List[Dict]:
        """
        Filters out the deployments currently cooling down from the list of healthy deployments

Args:
            healthy_deployments: List of healthy deployments
            cooldown_deployments: List of model_ids cooling down. cooldown_deployments is a list of model_id's cooling down, cooldown_deployments = ["16700539-b3cd-42f4-b426-6a12a1bb706a", "16700539-b3cd-42f4-b426-7899"]

Returns:
            List of healthy deployments
        """
        if verbose_router_logger.isEnabledFor(logging.DEBUG):
            verbose_router_logger.debug(f"cooldown deployments: {cooldown_deployments}")
        # Convert to set for O(1) lookup and use list comprehension for O(n) filtering
        cooldown_set = set(cooldown_deployments)
        return [deployment for deployment in healthy_deployments if deployment["model_info"]["id"] not in cooldown_set]

def _filter_blocked_deployments(self, healthy_deployments: List[Dict]) -> List[Dict]:
        """
        Filters out deployments that an admin has paused via `LiteLLM_ProxyModelTable.blocked`.

Applied alongside the cooldown filter on every routing entry point that calls
        `_common_checks_available_deployment` directly — the primary sync/async path,
        the sync pass-through path, and the retry / health-check helpers — so paused
        deployments never serve a request. The async pass-through path inherits this
        filter through its delegation to `async_get_healthy_deployments`.
        """
        return [
            deployment
            for deployment in healthy_deployments
            if (deployment.get("model_info") or {}).get("blocked") is not True
        ]","content_hash":"35f35fd11577b217ac6b3a3acf8fc758236bcc3139112ada2b6730262a821acf","chunk_metadata":{"ordinal":302,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/litellm-34399-kaitlyn","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00302","vector":{"bm25":{"indices":[63196122,136345932,138515167,142517664,176587294,201105118,206707636,237453754,376835143,402167784,403465192,405807530,416094519,443994268,448220673,454222729,455026286,482263480,491396510,505772525,549248996,549546528,550693654,563226112,608954612,663089258,670727360,671481495,672811249,691981403,717265138,728008763,766710245,772165269,780249753,782301825,815826517,850522271,917314569,920073456,926244272,992854116,1036623567,1050315610,1119753640,1132748958,1135795808,1153012442,1169853166,1170138678,1172383616,1179585255,1241066858,1258039968,1297380231,1299665196,1331432587,1338388647,1358215157,1412284840,1430125705,1478694944,1488837928,1519078073,1539641452,1561193773,1581361369,1605015950,1610788695,1615682969,1635977013,1637669348,1672064345,1717991430,1763574823,1790752915,1838689002,1853176582,1858177504,1887486930,1972720242,1986137636,1998848851,2021799277,2045916435,2086848750,2143830595],"values":[1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.7009966,1.1701641,1.5277363,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.5277363,1.1701641,1.1701641,1.5277363,1.5277363,1.1701641,1.1701641,1.7009966,1.1701641,1.5277363,1.8707235,1.5277363,1.5277363,1.5277363,1.1701641,1.1701641,1.5277363,1.1701641,1.1701641,1.1701641,1.8032498,1.7009966,1.1701641,1.1701641,1.1701641,1.5277363,1.1701641,1.5277363,1.5277363,1.5277363,1.5277363,1.9185829,2.0698817,1.1701641,1.1701641,1.1701641,1.7009966,1.1701641,1.1701641,1.1701641,1.1701641,1.7009966,1.5277363,1.1701641,1.1701641,1.1701641,1.1701641,1.1701641,1.7009966,1.5277363,1.1701641,1.1701641,1.8707235,1.5277363,1.1701641,1.52