@staticmethod
    def _is_deployment_blocked(deployment: "Deployment") -> bool:
        """
        Returns True when a `Deployment` Pydantic instance carries the admin-paused
        flag. Used by credential-lookup helpers so passthrough file / batch endpoints
        cannot bypass the pause by resolving credentials directly.
        """
        model_info = getattr(deployment, "model_info", None)
        if model_info is None:
            return False
        return getattr(model_info, "blocked", None) is True

async def _async_filter_health_check_unhealthy_deployments(
        self,
        healthy_deployments: List[Dict],
        parent_otel_span: Optional[Span] = None,
    ) -> List[Dict]:
        """
        Filter out deployments marked unhealthy by background health checks.
        No-op when enable_health_check_routing is False.
        Returns all deployments if health state is unavailable, stale, or would
        exclude every candidate (safety net).
        """
        if not self.enable_health_check_routing:
            return healthy_deployments

# When allowed_fails_policy is set, cooldown is the sole routing exclusion
        # mechanism -- skip the binary health check filter so the policy threshold
        # is respected before any deployment is excluded.
        if self.allowed_fails_policy is not None:
            return healthy_deployments

unhealthy_ids = await self.health_state_cache.async_get_unhealthy_deployment_ids(
            parent_otel_span=parent_otel_span
        )
        if not unhealthy_ids:
            return healthy_deployments

filtered = [d for d in healthy_deployments if d["model_info"]["id"] not in unhealthy_ids]

if not filtered:
            verbose_router_logger.warning("All deployments marked unhealthy by health checks, bypassing health filter")
            return healthy_deployments

return filtered","content_hash":"a5a3936e0445bb9f80b6e19caf2ce485395270faf99082598de10242c25f1d58","chunk_metadata":{"ordinal":303,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/litellm-34399-kaitlyn","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00303","vector":{"bm25":{"indices":[1082299,11875599,21141582,63196122,114246254,117848935,131900689,136345932,138515167,152217691,152900484,176587294,182765111,201105118,254838516,257141012,257581069,262689147,390204765,402167784,403465192,405807530,443994268,448220673,454222729,491396510,505715833,516204289,520427161,523661903,549248996,550693654,572399988,580751866,631232498,640124220,648501015,672811249,716765060,717265138,728008763,766710245,772165269,780249753,792873749,823134346,888000370,917314569,926244272,956524161,965664421,967714644,997012898,1003647919,1003798966,1009084850,1050007059,1050315610,1105983500,1122897543,1132748958,1150939219,1153295626,1164397671,1198866113,1220006796,1258039968,1293835645,1297380231,1299665196,1319100357,1331432587,1338388647,1357846105,1358215157,1413186873,1428545878,1430125705,1437097820,1439015410,1478694944,1515372845,1519078073,1539641452,1559838443,1581361369,1590456296,1610788695,1615682969,1628046089,1636998148,1672064345,1707643534,1737061407,1746366895,1748272243,1751311563,1763574823,1799936523,1807131503,1810453357,1830646559,1838535212,1838689002,1853176582,1887486930,1889346259,1945423217,1969182875,1975086144,1986137636,1998848851,2021799277,2059213458,2064885619,2065015680,2142435286,2143830595],"values":[1.4332613,1.062842,1.062842,1.4332613,1.062842,1.062842,1.6216527,1.062842,1.8670645,1.4332613,1.062842,1.4332613,1.062842,1.062842,1.4332613,1.4332613,1.062842,1.062842,1.4332613,1.4332613,1.6216527,1.062842,1.062842,1.735727,1.062842,1.6216527,1.062842,1.062842,1.062842,1.062842,1.4332613,1.4332613,1.4332613,1.062842,1.062842,1.062842,1.062842,1.9404798,1.062842,1.4332613,1.062842,1.062842,1.06284