def _filter_cooldown_deployments(
        self, healthy_deployments: List[Dict], cooldown_deployments: List[str]
    ) -> List[Dict]:
        """
        Filters out the deployments currently cooling down from the list of healthy deployments

Args:
            healthy_deployments: List of healthy deployments
            cooldown_deployments: List of model_ids cooling down. cooldown_deployments is a list of model_id's cooling down, cooldown_deployments = ["16700539-b3cd-42f4-b426-6a12a1bb706a", "16700539-b3cd-42f4-b426-7899"]

Returns:
            List of healthy deployments
        """
        if verbose_router_logger.isEnabledFor(logging.DEBUG):
            verbose_router_logger.debug(f"cooldown deployments: {cooldown_deployments}")
        # Convert to set for O(1) lookup and use list comprehension for O(n) filtering
        cooldown_set = set(cooldown_deployments)
        return [deployment for deployment in healthy_deployments if deployment["model_info"]["id"] not in cooldown_set]

def _filter_blocked_deployments(self, healthy_deployments: List[Dict]) -> List[Dict]:
        """
        Filters out deployments that an admin has paused via `LiteLLM_ProxyModelTable.blocked`.

Applied alongside the cooldown filter on every routing entry point that calls
        `_common_checks_available_deployment` directly — the primary sync/async path,
        the sync pass-through path, and the retry / health-check helpers — so paused
        deployments never serve a request. The async pass-through path inherits this
        filter through its delegation to `async_get_healthy_deployments`.
        """
        return [
            deployment
            for deployment in healthy_deployments
            if (deployment.get("model_info") or {}).get("blocked") is not True
        ]","content_hash":"18f3122f048a9abdedb822778aff296b84891e4e3fcca466c2a35fe405559d76","chunk_metadata":{"ordinal":303,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/kaitlyn-nguyen/litellm-34399","team":""}}},"conflict_id":null,"change_id":"qdrant:1272f85f88703f307820a652"},{"table":"knowledge","key":{"id":"enterprise_cb873e2345a508fa44720d93:00304"},"change":"modified","before":{"id":"enterprise_cb873e2345a508fa44720d93:00304","vector":{"bm25":{"indices":[62694798,131900689,136345932,176587294,192819851,325678202,390204765,402167784,403465192,417689373,437666037,438080992,448220673,454222729,486608410,491396510,499549952,523529899,548763890,549248996,549546528,550693654,563226112,572399988,599316540,610868587,655955059,672811249,690815750,715022825,717265138,728008763,766710245,772165269,780249753,805216051,823134346,888000370,917314569,926244272,956524161,965664421,997012898,1003647919,1009084850,1032370710,1050007059,1050315610,1100855371,1170138678,1228704792,1297380231,1299144729,1299665196,1331432587,1357846105,1430125705,1439015410,1449660732,1519078073,1539641452,1575082431,1581361369,1610788695,1615682969,1617757292,1620849882,1636998148,1653414040,1737061407,1746366895,1751311563,1763574823,1810936627,1833610515,1838689002,1853176582,1887486930,1934430699,1980155820,1986137636,1998848851,2021799277,2084206835,2138315291,2143830595],"values":[1.08873,1.8270291,1.08873,1.4566145,1.4566145,1.08873,1.6415039,1.08873,1.4566145,1.08873,1.08873,1.08873,1.08873,1.08873,1.08873,1.9510674,1.08873,1.4566145,1.4566145,1.08873,1.6415039,1.4566145,1.4566145,1.9200312,1.4566145,1.08873,1.8801535,1.6415039,1.08873,1.08873,1.4566145,1.4566145,1.08873,1.08873,1.7527425,1.08873,1.7527425,1.08873,1.9200312,1.08873,1.08873,1.6415039,1.4566145,1.08873,1.08873,1.08873,1.4566145,1.8270291,1.08873,1.6415039,1.8801535,1.9510674,1.08873,1.6415039,1.08873,1.7527425,1.9759092,1.08873,1.08873,1.08873,1.08873,1.4566145,2.0398407,1.0887