def _try_early_resolve_deployments_for_model_not_in_names(
        self,
        model: str,
        request_team_id: Optional[str],
        include_team_models: bool = False,
    ) -> Optional[Tuple[str, Union[List, Dict]]]:
        """
        When ``model`` is not in ``self.model_names``, try team routes, pattern routes,
        team pattern routers, then default deployment. Returns None if none apply.
        """
        if model in self.model_names:
            return None
        # Check for team-specific deployments by team_public_model_name.
        # This intentionally takes priority over team pattern routers below,
        # so that named team deployments shadow wildcard/pattern routes.
        if request_team_id is not None:
            team_deployments = self._get_all_deployments(model_name=model, team_id=request_team_id)
            if team_deployments:
                return model, team_deployments
        elif include_team_models:
            team_deployments = [
                self.model_list[index]
                for (_, public_model_name), indices in self.team_model_to_deployment_indices.items()
                if public_model_name == model
                for index in indices
            ]
            team_ids = {
                team_id
                for deployment in team_deployments
                for team_id in [(deployment.get("model_info") or {}).get("team_id")]
                if team_id is not None
            }
            if len(team_ids) > 1:
                raise litellm.BadRequestError(
                    message=(
                        f"Model name '{model}' matches deployments from multiple teams. "
                        "Specify the deployment ID directly to disambiguate."
                    ),
                    model=model,
                    llm_provider="",
                )
            if team_deployments:
                return model, team_deployments

pattern_deployments = self.pattern_router.get_deployments_by_pattern(
            model=model,
        )

if pattern_deployments:
            return model, pattern_deployments","content_hash":"bb2a3ed3041947a7bd35346a86756aae42cb6f9f21b9ee136f484e5cd170eae3","chunk_metadata":{"ordinal":273,"document_path":"/code/litellm/litellm/router.py","document_kind":"source","workspace":"task/litellm-34399-kaitlyn","team":""}}},"after":{"id":"enterprise_cb873e2345a508fa44720d93:00273","vector":{"bm25":{"indices":[19522071,131900689,136345932,176587294,213600005,269443847,325678202,340581898,390204765,402167784,428684691,438080992,443994268,448220673,454222729,491396510,523529899,550693654,563226112,572399988,609270800,636226512,655955059,672811249,717265138,764297089,766710245,772165269,813056149,823134346,896827128,917314569,926244272,967714644,997012898,1003647919,1021187622,1036332678,1110626798,1132748958,1172383616,1258039968,1264091051,1331432587,1362436744,1430125705,1519078073,1524906076,1539641452,1554342659,1572251935,1590456296,1610788695,1615682969,1634511095,1699242642,1727379255,1748272243,1751311563,1763574823,1810453357,1838689002,1853176582,1887486930,1986137636,1998848851,2021799277,2121312113,2128973781,2143830595],"values":[1.2421702,1.9060512,1.2421702,1.5878206,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.9060512,1.2421702,1.2421702,1.9060512,1.2421702,1.5878206,1.5878206,1.7501553,1.2421702,1.2421702,1.5878206,1.2421702,1.5878206,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.5878206,1.2421702,1.2421702,1.2421702,1.5878206,1.2421702,1.2421702,1.7501553,1.2421702,1.8444408,2.0924358,1.2421702,1.2421702,1.2421702,1.2421702,1.8444408,1.2421702,1.7501553,1.5878206,1.8444408,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.5878206,1.2421702,1.5878206,1.7501553,1.2421702,1.2421702,1.981703,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.2421702,1.5878206,1.9060512]}},"payload":{"document_id":"enterprise_cb873e2345a508fa44720d93","chunk_id":"enterprise_cb873e2345a508fa44720d93:00273","ordinal":273,"text":"[Document context]
